#include <stdio.h>

int is_leap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

int main() {
    int years[] = {1900, 2000, 2023, 2024};
    for (int i = 0; i < 4; i++) {
        printf("%d: %s\n", years[i], is_leap(years[i]) ? "leap" : "not leap");
    }
    return 0;
}
